package com.example.sgva.infrastructure.web

import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.ResultadoIngesta
import com.example.sgva.usecases.ConsultarResultadoEncuestaPreguntaUseCase
import com.example.sgva.usecases.ProcesarResultadosEncuestaPreguntaUseCase
import com.example.sgva.usecases.RegistrarResultadoEncuestaPreguntaUseCase
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController
import org.springframework.web.multipart.MultipartFile

/**
 * Adaptador de entrada REST (Primary Adapter) del Módulo 4 (`DESIGN_SGVA.md`
 * §4): expone el registro individual, la consulta y la carga masiva desde
 * archivo de resultados de encuesta por pregunta. Delega toda la lógica a los
 * casos de uso; no reimplementa reglas de negocio.
 *
 * A diferencia de [DocenteController] o [EncuestaController], no expone un
 * `GET /{id}`: la entidad no tiene un `id` propio, su clave natural es la
 * combinación de `programa`, `periodo` y `codigoPregunta` (`DESIGN_SGVA.md` §1).
 */
@RestController
@RequestMapping("/api/resultados-encuesta-pregunta")
class ResultadoEncuestaPreguntaController(
    private val registrarResultadoEncuestaPregunta: RegistrarResultadoEncuestaPreguntaUseCase,
    private val consultarResultadoEncuestaPregunta: ConsultarResultadoEncuestaPreguntaUseCase,
    private val procesarResultadosEncuestaPregunta: ProcesarResultadosEncuestaPreguntaUseCase,
) {

    @PostMapping
    fun registrar(@RequestBody resultado: ResultadoEncuestaPregunta): ResponseEntity<ResultadoEncuestaPregunta> {
        val registrado = registrarResultadoEncuestaPregunta.ejecutar(resultado)
        return ResponseEntity.status(201).body(registrado)
    }

    @GetMapping
    fun listar(
        @RequestParam programa: String?,
        @RequestParam periodo: String?,
    ): List<ResultadoEncuestaPregunta> =
        consultarResultadoEncuestaPregunta.listarTodos()
            .filter { programa == null || it.programa == programa }
            .filter { periodo == null || it.periodo == periodo }

    @PostMapping("/archivos", consumes = ["multipart/form-data"])
    fun cargarArchivo(@RequestParam("archivo") archivo: MultipartFile): ResponseEntity<ResultadoIngesta> {
        val resultado = procesarResultadosEncuestaPregunta.ejecutar(
            archivo.originalFilename ?: archivo.name,
            archivo.bytes,
        )
        return ResponseEntity.status(201).body(resultado)
    }
}

package com.example.sgva.infrastructure.web

import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.ResultadoIngesta
import com.example.sgva.usecases.ConsultarEvaluacionDocumentalUseCase
import com.example.sgva.usecases.ProcesarEvaluacionesDocumentalesUseCase
import com.example.sgva.usecases.RegistrarEvaluacionDocumentalUseCase
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController
import org.springframework.web.multipart.MultipartFile

/**
 * Adaptador de entrada REST (Primary Adapter) del Módulo 4 (`DESIGN_SGVA.md`
 * §4): expone el registro individual, la consulta y la carga masiva desde
 * archivo de evaluaciones documentales. Delega toda la lógica a los casos de
 * uso; no reimplementa reglas de negocio.
 *
 * A diferencia de [DocenteController] o [EncuestaController], no expone un
 * `GET /{id}`: la entidad no tiene un `id` propio, su clave natural es la
 * combinación de `programa`, `periodo` y `caracteristica` (`DESIGN_SGVA.md` §1).
 */
@RestController
@RequestMapping("/api/evaluaciones-documentales")
class EvaluacionDocumentalController(
    private val registrarEvaluacionDocumental: RegistrarEvaluacionDocumentalUseCase,
    private val consultarEvaluacionDocumental: ConsultarEvaluacionDocumentalUseCase,
    private val procesarEvaluacionesDocumentales: ProcesarEvaluacionesDocumentalesUseCase,
) {

    @PostMapping
    fun registrar(@RequestBody evaluacion: EvaluacionDocumental): ResponseEntity<EvaluacionDocumental> {
        val registrada = registrarEvaluacionDocumental.ejecutar(evaluacion)
        return ResponseEntity.status(201).body(registrada)
    }

    @GetMapping
    fun listar(
        @RequestParam programa: String?,
        @RequestParam periodo: String?,
    ): List<EvaluacionDocumental> =
        consultarEvaluacionDocumental.listarTodas()
            .filter { programa == null || it.programa == programa }
            .filter { periodo == null || it.periodo == periodo }

    @PostMapping("/archivos", consumes = ["multipart/form-data"])
    fun cargarArchivo(@RequestParam("archivo") archivo: MultipartFile): ResponseEntity<ResultadoIngesta> {
        val resultado = procesarEvaluacionesDocumentales.ejecutar(
            archivo.originalFilename ?: archivo.name,
            archivo.bytes,
        )
        return ResponseEntity.status(201).body(resultado)
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.ResultadoAutoevaluacion

/**
 * Módulo 4 — resultado de autoevaluación del programa (`DESIGN_SGVA.md` §0.1
 * "Reglas de cálculo del resultado de autoevaluación" y §2).
 *
 * Calcula, para un [programa] y un [periodo], el promedio por característica,
 * por factor y global del modelo institucional de 12 factores y 48
 * características, a partir de los `ResultadoEncuestaPregunta` y
 * `EvaluacionDocumental` ya registrados. El universo de factores y
 * características, y todos los pesos usados en la mezcla, provienen
 * exclusivamente de [configuracion]: este caso de uso no hardcodea ningún
 * peso ni ningún identificador de factor o característica.
 *
 * Aplica exactamente las reglas de `DESIGN_SGVA.md` §0.1, sin criterios
 * adicionales no documentados.
 */
class CalcularResultadoAutoevaluacionUseCase(
    private val repositorio: AcademicDataRepository,
    private val configuracion: ConfiguracionPonderaciones,
) {

    fun ejecutar(programa: String, periodo: String): ResultadoAutoevaluacion {
        val promediosEncuestaPorCaracteristica = repositorio.listarResultadosEncuestaPregunta()
            .filter { it.programa == programa && it.periodo == periodo }
            .groupBy { it.caracteristica }
            .mapValues { (_, resultados) -> promedioDeEncuesta(resultados.mapNotNull { it.promedio }) }

        val documentalPorCaracteristica = repositorio.listarEvaluacionesDocumentales()
            .filter { it.programa == programa && it.periodo == periodo }
            .associateBy { it.caracteristica }

        val promediosPorCaracteristica = configuracion.caracteristicas.associate { caracteristica ->
            caracteristica.id to promedioDeCaracteristica(
                resultadoEncuesta = promediosEncuestaPorCaracteristica[caracteristica.id],
                documental = documentalPorCaracteristica[caracteristica.id]?.calificacion,
            )
        }

        val promediosPorFactor = configuracion.pesosFactores.keys.associateWith { factor ->
            promedioPonderadoReponderado(
                caracteristicasDelFactor(factor).mapNotNull { caracteristica ->
                    promediosPorCaracteristica[caracteristica.id]?.let { it to caracteristica.ponderacion }
                },
            )
        }

        val promedioGlobal = promedioPonderadoReponderado(
            configuracion.pesosFactores.mapNotNull { (factor, peso) ->
                promediosPorFactor[factor]?.let { it to peso }
            },
        )

        return ResultadoAutoevaluacion(
            programa = programa,
            periodo = periodo,
            promediosPorCaracteristica = promediosPorCaracteristica,
            promediosPorFactor = promediosPorFactor,
            promedioGlobal = promedioGlobal,
        )
    }

    private fun caracteristicasDelFactor(factor: String): List<Caracteristica> =
        configuracion.caracteristicas.filter { it.factor == factor }

    /**
     * Regla 1 de §0.1: promedio de los promedios de las preguntas con valor
     * de la característica, o ausente si ninguna pregunta tiene valor.
     */
    private fun promedioDeEncuesta(promedios: List<Double>): Double? =
        if (promedios.isEmpty()) null else promedios.average()

    /**
     * Regla 2 de §0.1: mezcla documental/encuesta de una característica, el
     * valor documental completo si la encuesta está ausente, o ausente si no
     * hay evaluación documental.
     */
    private fun promedioDeCaracteristica(resultadoEncuesta: Double?, documental: Double?): Double? = when {
        documental == null -> null
        resultadoEncuesta == null -> documental
        else -> documental * configuracion.pesoDocumental + resultadoEncuesta * configuracion.pesoEncuestas
    }

    /**
     * Reglas 3 y 4 de §0.1: promedio ponderado de los valores presentes,
     * reponderando sus pesos de configuración entre sí. Ausente si no hay
     * ningún valor presente, o si los pesos de los valores presentes suman
     * cero (no hay ninguna base de reponderación válida).
     */
    private fun promedioPonderadoReponderado(valoresConPeso: List<Pair<Double, Double>>): Double? {
        if (valoresConPeso.isEmpty()) return null
        val sumaPesos = valoresConPeso.sumOf { it.second }
        if (sumaPesos == 0.0) return null
        return valoresConPeso.sumOf { (valor, peso) -> valor * peso } / sumaPesos
    }
}

package com.example.sgva.infrastructure.web

import com.example.sgva.infrastructure.reporting.GeneradorReportePdf
import com.example.sgva.usecases.GenerarReporteEjecutivoUseCase
import org.springframework.http.ContentDisposition
import org.springframework.http.HttpHeaders
import org.springframework.http.MediaType
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController

/**
 * Adaptador de entrada REST (Primary Adapter) de los reportes ejecutivos
 * (Fase 4 del anteproyecto — integración de reportes, `DESIGN_SGVA.md` §4).
 * Delega la consolidación de datos en [GenerarReporteEjecutivoUseCase] y la
 * generación física del PDF en [GeneradorReportePdf]; no reimplementa
 * lógica de negocio ni de renderizado.
 */
@RestController
@RequestMapping("/api/reportes")
class ReporteController(
    private val generarReporteEjecutivo: GenerarReporteEjecutivoUseCase,
    private val generadorReportePdf: GeneradorReportePdf,
) {

    @GetMapping("/ejecutivo", produces = [MediaType.APPLICATION_PDF_VALUE])
    fun obtenerReporteEjecutivo(
        @RequestParam periodo: String?,
        @RequestParam facultad: String?,
        @RequestParam cohorte: String?,
    ): ResponseEntity<ByteArray> {
        val reporte = generarReporteEjecutivo.ejecutar(periodo, facultad, cohorte)
        val pdf = generadorReportePdf.generar(reporte)

        val nombreArchivo = periodo?.trim()?.takeIf { it.isNotEmpty() }
            ?.let { "reporte-ejecutivo-$it.pdf" }
            ?: "reporte-ejecutivo.pdf"

        return ResponseEntity.ok()
            .contentType(MediaType.APPLICATION_PDF)
            .header(
                HttpHeaders.CONTENT_DISPOSITION,
                ContentDisposition.attachment().filename(nombreArchivo).build().toString(),
            )
            .body(pdf)
    }
}

package com.example.sgva.infrastructure.web

import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.DominioException
import com.example.sgva.domain.EntidadDuplicadaException
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.http.converter.HttpMessageNotReadableException
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice

/** Cuerpo de respuesta uniforme para los errores traducidos por [ManejadorGlobalDeErrores]. */
data class ErrorRespuesta(val mensaje: String)

/**
 * Traduce las excepciones de dominio (`DESIGN_SGVA.md` §0.1, §5) a respuestas
 * HTTP consistentes para todos los controladores REST. La validación de
 * negocio ya ocurrió en el dominio o en los casos de uso (constructores de
 * [com.example.sgva.domain.Estudiante]/[com.example.sgva.domain.Docente],
 * reglas de aplicación de los casos de uso); este adaptador solo traduce el
 * resultado a un código HTTP, no reimplementa reglas.
 */
@RestControllerAdvice
class ManejadorGlobalDeErrores {

    /** Identificador ya registrado: la solicitud es válida pero entra en conflicto con el estado actual. */
    @ExceptionHandler(EntidadDuplicadaException::class)
    fun manejarDuplicado(ex: EntidadDuplicadaException): ResponseEntity<ErrorRespuesta> =
        responder(HttpStatus.CONFLICT, ex.message)

    /** No hay datos suficientes para calcular el indicador solicitado. */
    @ExceptionHandler(DatosInsuficientesException::class)
    fun manejarDatosInsuficientes(ex: DatosInsuficientesException): ResponseEntity<ErrorRespuesta> =
        responder(HttpStatus.UNPROCESSABLE_CONTENT, ex.message)

    /** Resto de violaciones de reglas de negocio (formato inválido, campo vacío, archivo no soportado, etc.). */
    @ExceptionHandler(DominioException::class)
    fun manejarDominio(ex: DominioException): ResponseEntity<ErrorRespuesta> =
        responder(HttpStatus.BAD_REQUEST, ex.message)

    /**
     * El cuerpo JSON no pudo deserializarse. Si la causa raíz es una
     * [DominioException] —p. ej. el `init` de [com.example.sgva.domain.Estudiante]
     * rechazó el `puntajeSaberPro`— se conserva su mensaje; si es un problema de
     * formato ajeno al dominio (JSON corrupto, campo faltante), se responde con
     * un mensaje genérico.
     */
    @ExceptionHandler(HttpMessageNotReadableException::class)
    fun manejarCuerpoInvalido(ex: HttpMessageNotReadableException): ResponseEntity<ErrorRespuesta> {
        val causaDominio = generateSequence<Throwable>(ex) { it.cause }
            .filterIsInstance<DominioException>()
            .firstOrNull()
        return responder(HttpStatus.BAD_REQUEST, causaDominio?.message ?: "El cuerpo de la solicitud no es válido.")
    }

    private fun responder(estado: HttpStatus, mensaje: String?): ResponseEntity<ErrorRespuesta> =
        ResponseEntity.status(estado).body(ErrorRespuesta(mensaje ?: estado.reasonPhrase))
}

package com.example.sgva.infrastructure.web

import com.example.sgva.application.RepositorioAcademicoFalso
import com.example.sgva.domain.EvaluacionDocumental
import org.hamcrest.Matchers.containsString
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest
import org.springframework.context.annotation.Import
import org.springframework.http.MediaType
import org.springframework.mock.web.MockMultipartFile
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.status
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Pruebas de integración con `MockMvc` de [EvaluacionDocumentalController]:
 * mismo enfoque que [ResultadoEncuestaPreguntaControllerTest], ejercitando
 * controlador, casos de uso reales y [ManejadorGlobalDeErrores] juntos.
 */
@WebMvcTest(controllers = [EvaluacionDocumentalController::class])
@Import(ConfiguracionCasosDeUsoDePrueba::class)
class EvaluacionDocumentalControllerTest {

    @Autowired
    private lateinit var mockMvc: MockMvc

    @Autowired
    private lateinit var repositorio: RepositorioAcademicoFalso

    @BeforeEach
    fun limpiar() {
        repositorio.limpiar()
    }

    @Test
    fun `registrar una evaluacion valida devuelve 201 con el recurso creado y su valoracion derivada`() {
        mockMvc.perform(
            post("/api/evaluaciones-documentales")
                .contentType(MediaType.APPLICATION_JSON)
                .content(
                    """{"programa":"EGSTI","caracteristica":"1.1","periodo":"20261",
                        "calificacion":4.7,"justificacion":"Evidencia consistente"}
                    """.trimIndent(),
                ),
        )
            .andExpect(status().isCreated)
            .andExpect(jsonPath("$.caracteristica").value("1.1"))
            .andExpect(jsonPath("$.calificacion").value(4.7))
            .andExpect(jsonPath("$.valoracionCualitativa").value("SE_CUMPLE_PLENAMENTE"))

        assertEquals(1, repositorio.listarEvaluacionesDocumentales().size)
    }

    @Test
    fun `registrar una clave natural ya existente devuelve 409 sin sobrescribir el original`() {
        repositorio.guardarEvaluacionDocumental(evaluacion(caracteristica = "1.1", calificacion = 4.5))

        mockMvc.perform(
            post("/api/evaluaciones-documentales")
                .contentType(MediaType.APPLICATION_JSON)
                .content(
                    """{"programa":"EGSTI","caracteristica":"1.1","periodo":"20261","calificacion":1.0}""",
                ),
        )
            .andExpect(status().isConflict)

        assertEquals(4.5, repositorio.buscarEvaluacionDocumental("EGSTI", "20261", "1.1")?.calificacion)
    }

    @Test
    fun `registrar una calificacion de 0 devuelve 400 con el mensaje de dominio`() {
        mockMvc.perform(
            post("/api/evaluaciones-documentales")
                .contentType(MediaType.APPLICATION_JSON)
                .content(
                    """{"programa":"EGSTI","caracteristica":"1.1","periodo":"20261","calificacion":0.0}""",
                ),
        )
            .andExpect(status().isBadRequest)

        assertTrue(repositorio.listarEvaluacionesDocumentales().isEmpty())
    }

    @Test
    fun `listar devuelve las evaluaciones registradas en orden de insercion`() {
        repositorio.guardarEvaluacionDocumental(evaluacion(caracteristica = "1.1"))
        repositorio.guardarEvaluacionDocumental(evaluacion(caracteristica = "1.2"))

        mockMvc.perform(get("/api/evaluaciones-documentales"))
            .andExpect(status().isOk)
            .andExpect(jsonPath("$.length()").value(2))
            .andExpect(jsonPath("$[0].caracteristica").value("1.1"))
            .andExpect(jsonPath("$[1].caracteristica").value("1.2"))
    }

    @Test
    fun `listar filtra por programa y periodo`() {
        repositorio.guardarEvaluacionDocumental(evaluacion(caracteristica = "1.1", programa = "EGSTI"))
        repositorio.guardarEvaluacionDocumental(evaluacion(caracteristica = "1.2", programa = "OTRO"))

        mockMvc.perform(get("/api/evaluaciones-documentales").param("programa", "EGSTI"))
            .andExpect(status().isOk)
            .andExpect(jsonPath("$.length()").value(1))
            .andExpect(jsonPath("$[0].programa").value("EGSTI"))
    }

    @Test
    fun `cargar un archivo csv valido registra las evaluaciones y devuelve 201 con el resumen`() {
        val csv = """
            programa,caracteristica,periodo,calificacion,justificacion,sugerenciasMejora
            EGSTI,1.1,20261,4.7,Evidencia consistente,
            EGSTI,1.2,20261,3.5,,Fortalecer el seguimiento
        """.trimIndent()
        val archivo = MockMultipartFile("archivo", "evaluaciones.csv", "text/csv", csv.toByteArray())

        mockMvc.perform(multipart("/api/evaluaciones-documentales/archivos").file(archivo))
            .andExpect(status().isCreated)
            .andExpect(jsonPath("$.nombreArchivo").value("evaluaciones.csv"))
            .andExpect(jsonPath("$.totalRegistrosLeidos").value(2))
            .andExpect(jsonPath("$.registrados").value(2))
            .andExpect(jsonPath("$.omitidos.length()").value(0))

        assertEquals(2, repositorio.listarEvaluacionesDocumentales().size)
    }

    @Test
    fun `cargar un archivo con formato no soportado devuelve 400 sin registrar nada`() {
        val archivo = MockMultipartFile(
            "archivo",
            "evaluaciones.txt",
            "text/plain",
            "programa\nEGSTI".toByteArray(),
        )

        mockMvc.perform(multipart("/api/evaluaciones-documentales/archivos").file(archivo))
            .andExpect(status().isBadRequest)
            .andExpect(jsonPath("$.mensaje").value(containsString(".csv")))

        assertTrue(repositorio.listarEvaluacionesDocumentales().isEmpty())
    }

    private fun evaluacion(
        caracteristica: String,
        programa: String = "EGSTI",
        calificacion: Double = 4.0,
    ): EvaluacionDocumental = EvaluacionDocumental(
        programa = programa,
        caracteristica = caracteristica,
        periodo = "20261",
        calificacion = calificacion,
    )
}

package com.example.sgva.application

import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.TipoEstamento
import com.example.sgva.usecases.CalcularResultadoAutoevaluacionUseCase
import org.junit.jupiter.api.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull

/**
 * Verifica `CalcularResultadoAutoevaluacionUseCase` contra las reglas de
 * cálculo de `DESIGN_SGVA.md` §0.1, con un catálogo sintético de dos factores
 * (F1 con C1/C2, F2 con C3/C4) y una mezcla encuestas/documental de 40 %/60 %.
 * Los pesos no corresponden al modelo 2025 real: son datos de prueba para
 * aislar cada regla.
 */
class CalcularResultadoAutoevaluacionUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()

    private val configuracion = ConfiguracionPonderaciones(
        caracteristicas = listOf(
            Caracteristica(id = "C1", nombre = "Característica 1", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C2", nombre = "Característica 2", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C3", nombre = "Característica 3", factor = "F2", ponderacion = 0.3),
            Caracteristica(id = "C4", nombre = "Característica 4", factor = "F2", ponderacion = 0.7),
        ),
        pesosFactores = mapOf("F1" to 0.6, "F2" to 0.4),
        pesoEncuestas = 0.4,
        pesoDocumental = 0.6,
    )

    private val useCase = CalcularResultadoAutoevaluacionUseCase(repositorio, configuracion)

    private fun registrarPregunta(
        codigoPregunta: String,
        caracteristica: String,
        promedio: Double?,
    ) {
        repositorio.guardarResultadoEncuestaPregunta(
            ResultadoEncuestaPregunta(
                programa = "EGSTI",
                periodo = "20261",
                codigoPregunta = codigoPregunta,
                caracteristica = caracteristica,
                estamentos = setOf(TipoEstamento.ESTUDIANTE),
                promedio = promedio,
            ),
        )
    }

    private fun registrarDocumental(caracteristica: String, calificacion: Double) {
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(
                programa = "EGSTI",
                caracteristica = caracteristica,
                periodo = "20261",
                calificacion = calificacion,
            ),
        )
    }

    @Test
    fun `el resultado de encuesta de una caracteristica es el promedio de los promedios de sus preguntas`() {
        registrarPregunta("A1", "C1", 3.0)
        registrarPregunta("A2", "C1", 5.0)
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta = (3.0 + 5.0) / 2 = 4.0; promedio = 4.0*0.6 + 4.0*0.4 = 4.0
        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `las preguntas con promedio null no cuentan en el resultado de encuesta`() {
        registrarPregunta("A1", "C1", 4.0)
        registrarPregunta("A2", "C1", null)
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta = 4.0 (la pregunta ausente no cuenta); promedio = 4.0*0.6 + 4.0*0.4 = 4.0
        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin ninguna pregunta con valor tiene resultado de encuesta ausente`() {
        registrarPregunta("A1", "C1", null)
        registrarDocumental("C1", 4.7)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta ausente -> el promedio es el valor documental completo, sin aplicar su peso de mezcla
        assertEquals(4.7, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin preguntas registradas tiene resultado de encuesta ausente`() {
        registrarDocumental("C1", 4.7)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(4.7, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica con encuesta y documental mezcla ambas fuentes con los pesos de la configuracion`() {
        registrarPregunta("A1", "C1", 2.0)
        registrarDocumental("C1", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // documental 5.0 * 0.6 + encuesta 2.0 * 0.4 = 3.0 + 0.8 = 3.8
        assertEquals(3.8, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin evaluacion documental es ausente aunque tenga encuesta`() {
        registrarPregunta("A1", "C1", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
    }

    @Test
    fun `una caracteristica sin ninguna fuente es ausente`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
    }

    @Test
    fun `el promedio de un factor reponderan los pesos de las caracteristicas presentes`() {
        // C1 (peso 0.5) ausente; solo C2 (peso 0.5) tiene documental.
        registrarDocumental("C2", 4.4)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
        // reponderado: solo C2 presente -> su peso se normaliza a 1.0, el promedio del factor es su propio valor
        assertEquals(4.4, resultado.promediosPorFactor["F1"]!!, 1e-9)
    }

    @Test
    fun `el promedio de un factor con todas sus caracteristicas presentes no cambia por la reponderacion`() {
        registrarDocumental("C1", 4.0)
        registrarDocumental("C2", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // 4.0*0.5 + 5.0*0.5 = 4.5 (los pesos ya suman 1.0, reponderar no cambia nada)
        assertEquals(4.5, resultado.promediosPorFactor["F1"]!!, 1e-9)
    }

    @Test
    fun `un factor sin ninguna caracteristica calculable es ausente`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorFactor["F1"])
    }

    @Test
    fun `el promedio global reponderan los pesos de los factores presentes`() {
        // F1 (peso 0.6) ausente por completo; solo F2 (peso 0.4) tiene datos.
        registrarDocumental("C3", 4.0)
        registrarDocumental("C4", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorFactor["F1"])
        // reponderado: solo F2 presente -> su peso se normaliza a 1.0
        assertEquals(4.0, resultado.promedioGlobal!!, 1e-9)
    }

    @Test
    fun `el promedio global con todos los factores y caracteristicas presentes no cambia por la reponderacion`() {
        registrarDocumental("C1", 4.0)
        registrarDocumental("C2", 5.0)
        registrarDocumental("C3", 3.0)
        registrarDocumental("C4", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        val f1 = 4.0 * 0.5 + 5.0 * 0.5 // 4.5
        val f2 = 3.0 * 0.3 + 4.0 * 0.7 // 3.7
        val global = f1 * 0.6 + f2 * 0.4

        assertEquals(f1, resultado.promediosPorFactor["F1"]!!, 1e-9)
        assertEquals(f2, resultado.promediosPorFactor["F2"]!!, 1e-9)
        assertEquals(global, resultado.promedioGlobal!!, 1e-9)
    }

    @Test
    fun `el promedio global es ausente cuando ningun factor es calculable`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promedioGlobal)
    }

    @Test
    fun `el resultado conserva el catalogo completo de caracteristicas y factores aunque esten ausentes`() {
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(setOf("C1", "C2", "C3", "C4"), resultado.promediosPorCaracteristica.keys)
        assertEquals(setOf("F1", "F2"), resultado.promediosPorFactor.keys)
    }

    @Test
    fun `el resultado solo usa datos del programa y periodo consultados`() {
        registrarDocumental("C1", 4.0)
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(programa = "OTRO-PROGRAMA", caracteristica = "C1", periodo = "20261", calificacion = 1.0),
        )
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(programa = "EGSTI", caracteristica = "C1", periodo = "20252", calificacion = 1.0),
        )

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `el resultado expone el programa y periodo consultados`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals("EGSTI", resultado.programa)
        assertEquals("20261", resultado.periodo)
    }
}

