    @Test
    fun `distribucion-formacion devuelve 200 con el porcentaje por nivel`() {
        guardarDocente(NivelFormacion.DOCTORADO)
        guardarDocente(NivelFormacion.MAESTRIA)
        guardarDocente(NivelFormacion.MAESTRIA)
        guardarDocente(NivelFormacion.MAESTRIA)

